import re
CASUAL_OPENER_RE = re.compile(r'^\s*(?:Hey there|Hi there|Hey|Hi|Sure thing|Alright|Oh|So,|Well,|Okay|No problem|Whoa|Got it|Gotcha|Yeah|Yo)\b', re.IGNORECASE)

def strip_casual_opener(text: str) -> str:
    parts = text.split('\n\n', 1)
    if len(parts) == 2 and CASUAL_OPENER_RE.match(parts[0]):
        return parts[1]
    return text

def _score_formality_fixed(text):
    text = strip_casual_opener(text)
    return _score_formality_orig(text)
